// Extraer y clasificar adjuntos (XML y PDF de Castilla)
const items = $input.all();
const results = [];

for (const item of items) {
  const binary = item.binary || {};
  let xmlAttachment = null;
  let pdfAttachment = null;

  for (const key of Object.keys(binary)) {
    const file = binary[key];
    const filename = (file.fileName || '').toLowerCase();
    if (filename.endsWith('.xml')) {
      xmlAttachment = { key, data: file, name: file.fileName };
    } else if (filename.endsWith('.pdf')) {
      pdfAttachment = { key, data: file, name: file.fileName };
    }
  }

  const emailDate = item.json.date ? new Date(item.json.date) : new Date();
  // Calcular número de semana ISO
  const target = new Date(emailDate.valueOf());
  const dayNr = (emailDate.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) {
    target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
  }
  const semanaCalculada = 1 + Math.ceil((firstThursday - target) / 604800000);

  const senderText = item.json.from?.text || item.json.from || 'facturaciondpc2@gmail.com';

  results.push({
    json: {
      email_from: senderText,
      email_subject: item.json.subject || '',
      email_date: emailDate.toISOString(),
      semana: semanaCalculada,
      tiene_xml: !!xmlAttachment,
      tiene_pdf: !!pdfAttachment,
      xml_key: xmlAttachment ? xmlAttachment.key : null,
      pdf_key: pdfAttachment ? pdfAttachment.key : null,
      pdf_filename: pdfAttachment ? pdfAttachment.name : 'factura_castilla.pdf'
    },
    binary: item.binary
  });
}

return results;

// Parser de Factura XML (CFDI 4.0 / 3.3 de DERIVADOS DE PETROLEO CASTILLA)
const items = $input.all();
const results = [];

for (const item of items) {
  const xmlKey = item.json.xml_key;
  let xmlString = '';

  if (xmlKey && item.binary && item.binary[xmlKey]) {
    const buffer = Buffer.from(item.binary[xmlKey].data, 'base64');
    xmlString = buffer.toString('utf-8');
  }

  let folio = 'S/F';
  let uuid = '';
  let proveedor = 'DERIVADOS DE PETROLEO CASTILLA';
  let rfcEmisor = 'DPC180725R47';
  let fechaFactura = item.json.email_date ? item.json.email_date.split('T')[0] : '';
  let litrosFacturados = 0;
  let precioUnitario = 0;
  let subtotal = 0;
  let iva = 0;
  let importeTotal = 0;

  if (xmlString) {
    // Extracción de Folio y Serie
    const folioMatch = xmlString.match(/Folio="([^"]+)"/i);
    const serieMatch = xmlString.match(/Serie="([^"]+)"/i);
    const serie = serieMatch ? serieMatch[1].trim() : '';
    const numFolio = folioMatch ? folioMatch[1].trim() : '';
    folio = serie + numFolio;
    if (!folio) folio = 'FAC-' + Date.now().toString().slice(-6);

    // Extracción de UUID CFDI
    const uuidMatch = xmlString.match(/UUID="([^"]+)"/i);
    if (uuidMatch) uuid = uuidMatch[1];

    // Extracción de Emisor
    const emisorMatch = xmlString.match(/<cfdi:Emisor[^>]*Nombre="([^"]+)"/i);
    const rfcMatch = xmlString.match(/<cfdi:Emisor[^>]*Rfc="([^"]+)"/i);
    if (emisorMatch && emisorMatch[1]) proveedor = emisorMatch[1];
    if (rfcMatch && rfcMatch[1]) rfcEmisor = rfcMatch[1];

    // Extracción de Fecha
    const fechaMatch = xmlString.match(/Fecha="([^"]+)"/i);
    if (fechaMatch) fechaFactura = fechaMatch[1].split('T')[0];

    // Extracción de Importes Totales
    const totalMatch = xmlString.match(/Total="([^"]+)"/i);
    const subtotalMatch = xmlString.match(/SubTotal="([^"]+)"/i);
    if (totalMatch) importeTotal = parseFloat(totalMatch[1]) || 0;
    if (subtotalMatch) subtotal = parseFloat(subtotalMatch[1]) || 0;
    iva = Math.round((importeTotal - subtotal) * 100) / 100;

    // Extracción de Concepto de Diésel / Litros
    const conceptoRegex = /<cfdi:Concepto[^>]*Cantidad="([^"]+)"[^>]*ValorUnitario="([^"]+)"[^>]*Importe="([^"]+)"/gi;
    let match;
    while ((match = conceptoRegex.exec(xmlString)) !== null) {
      litrosFacturados += parseFloat(match[1]) || 0;
      precioUnitario = parseFloat(match[2]) || precioUnitario;
    }

    // Fallback de extracción de cantidad
    if (litrosFacturados === 0) {
      const cantMatch = xmlString.match(/Cantidad="([^"]+)"/i);
      if (cantMatch) litrosFacturados = parseFloat(cantMatch[1]) || 0;
      const puMatch = xmlString.match(/ValorUnitario="([^"]+)"/i);
      if (puMatch) precioUnitario = parseFloat(puMatch[1]) || 0;
    }
  }

  // Estimación de litros si no se leyó cantidad y hay importe
  if (litrosFacturados === 0 && importeTotal > 0) {
    litrosFacturados = Math.round((importeTotal / 27.00) * 100) / 100;
    precioUnitario = 27.00;
  }

  results.push({
    json: {
      ...item.json,
      folio_factura: folio,
      uuid_cfdi: uuid,
      proveedor: proveedor,
      rfc_emisor: rfcEmisor,
      fecha_factura: fechaFactura,
      litros_facturados: litrosFacturados,
      precio_unitario: precioUnitario,
      subtotal: subtotal,
      iva: iva,
      importe_total: importeTotal,
      estatus: 'PENDIENTE_OBRA',
      folio_conciliacion: 'FAC-' + folio.replace(/[^a-zA-Z0-9]/g, '')
    }
  });
}

return results;
